#include "quotient.hpp"
int main(int argc,char**argv){try{F::init();string dir=argc>1?argv[1]:"evidence";int rc=argc>2?stoi(argv[2]):145049;ifstream in(dir+"/split_"+to_string(rc)+".txt");string line;getline(in,line);for(int i=0;i<3;i++)readPF(in);PF rem=readPF(in),x=PF::mon(1),h=x;assert(pgcd(rem,rem.deriv()).deg()==0);ofstream out(dir+"/ddf_"+to_string(rc)+".txt");out<<"DDF_V1 endpoint "<<rc<<"\n";int d=1;auto start=chrono::steady_clock::now();for(;2*d<=rem.deg();d++){h=power_mod(h,390625,rem);PF g=pgcd(rem,h-x);if(g.deg()>0){cerr<<"DDF "<<rc<<" degree "<<d<<" total "<<g.deg()<<"\n";out<<d<<" ";writePF(out,g);out.flush();rem=rem.exact(g);if(rem.deg()==0)break;h=h%rem;}if(d%10==0)cerr<<"DDF step "<<d<<" remaining "<<rem.deg()<<" elapsed "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n";}
if(rem.deg()>0){cerr<<"DDF final irreducible degree "<<rem.deg()<<"\n";out<<rem.deg()<<" ";writePF(out,rem);}cerr<<"DDF COMPLETE elapsed "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n";
}catch(exception&e){cerr<<"ERROR "<<e.what()<<"\n";return 1;}}
